import { getServerApiBase } from './server';

export interface ServerModelPricing {
  prompt?: number;
  completion?: number;
  [key: string]: number | undefined;
}

export interface ServerModelItem {
  id: string;
  name: string;
  description?: string;
  pricing?: ServerModelPricing;
  [key: string]: unknown;
}

export interface ServerModelListSuccess {
  provider: string;
  baseUrl: string;
  source: 'cache' | 'live';
  fetchedAt: string;
  expiresAt: string;
  configured: true;
  models: ServerModelItem[];
  raw?: unknown;
  listingSupported?: boolean;
  suggestions?: string[];
}

export type ServerModelListResult =
  | {
      kind: 'success';
      status: number;
      data: ServerModelListSuccess;
    }
  | {
      kind: 'not_configured';
      status: number;
      code: 'seat_not_configured';
      message: string;
      configured: false;
    }
  | {
      kind: 'error';
      status: number;
      code?: string;
      message: string;
      configured: false;
    };

export interface SeatConfigImportRequest {
  apiKey: string;
  baseUrl: string;
}

export interface SeatConfigImportResponse {
  success: true;
  provider: string;
  baseUrl: string;
  maskedApiKey: string;
  updatedAt: string;
  cacheInvalidated: boolean;
}

export class ServerApiError extends Error {
  readonly status: number;
  readonly code?: string;

  constructor(message: string, status: number, code?: string) {
    super(message);
    this.name = 'ServerApiError';
    this.status = status;
    this.code = code;
  }
}

export async function fetchServerModelList(
  apiToken: string,
  signal?: AbortSignal
): Promise<ServerModelListResult> {
  if (!apiToken) {
    throw new Error('API token is required to fetch server models');
  }

  const response = await fetch(`${getServerApiBase()}/ai/models`, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${apiToken}`,
      Accept: 'application/json',
    },
    credentials: 'omit',
    mode: 'cors',
    signal,
  });

  const status = response.status;
  const payload = await response.json().catch(() => ({}));

  if (response.ok) {
    const configuredFlag =
      payload && typeof payload === 'object' && 'configured' in payload
        ? (payload as any).configured
        : (payload as any)?.data?.configured;
    const payloadCode = (payload as any)?.code as string | undefined;

    if (configuredFlag === false || payloadCode === 'seat_not_configured') {
      return {
        kind: 'not_configured',
        status,
        code: 'seat_not_configured',
        message:
          (payload as any)?.message ||
          '席位未配置 AI 接入，请先在控制台配置 base_url 与 api_key',
        configured: false,
      };
    }

    return {
      kind: 'success',
      status,
      data: payload as ServerModelListSuccess,
    };
  }

  const code = payload.code as string | undefined;
  const message =
    (payload.message as string | undefined) || response.statusText;

  if (code === 'seat_not_configured') {
    return {
      kind: 'not_configured',
      status,
      code,
      message,
      configured: false,
    };
  }

  return {
    kind: 'error',
    status,
    code,
    message,
    configured: false,
  };
}

export async function uploadSeatConfig(
  apiToken: string,
  body: SeatConfigImportRequest,
  signal?: AbortSignal
): Promise<SeatConfigImportResponse> {
  if (!apiToken) {
    throw new Error('API token is required to upload seat config');
  }

  const response = await fetch(`${getServerApiBase()}/ai/seat-config/import`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiToken}`,
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
    credentials: 'omit',
    mode: 'cors',
    signal,
  });

  const payload = await response.json().catch(() => ({}));

  if (!response.ok) {
    const message =
      (payload.message as string | undefined) || response.statusText;
    const code = payload.code as string | undefined;
    throw new ServerApiError(message, response.status, code);
  }

  return payload as SeatConfigImportResponse;
}

// New AI config APIs for alignment with server
export interface AiConfigPayload {
  apiKey: string;
  baseUrl: string;
  model?: string;
}

export interface AiConfigResult {
  success: boolean;
  message?: string;
  needsModel?: boolean;
  triedModels?: Array<{ model: string; error: string }>;
  suggestions?: string[];
  error?: { code?: string; message?: string };
}

export async function testAiConfig(
  apiToken: string,
  body: AiConfigPayload,
  signal?: AbortSignal
): Promise<AiConfigResult> {
  const response = await fetch(
    `${getServerApiBase()}/apitokens/ai-config/test`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiToken}`,
        Accept: 'application/json',
      },
      body: JSON.stringify(body),
      credentials: 'omit',
      mode: 'cors',
      signal,
    }
  );

  const payload = (await response.json().catch(() => ({}))) as any;
  if (!response.ok) {
    return {
      success: false,
      message: payload?.message || response.statusText,
      error: payload?.error,
      needsModel: payload?.needsModel || payload?.error?.code === 'needs_model',
      triedModels: payload?.triedModels,
      suggestions: payload?.suggestions,
    };
  }
  return payload as AiConfigResult;
}

export async function putAiConfig(
  apiToken: string,
  licenseId: string,
  body: AiConfigPayload,
  signal?: AbortSignal
): Promise<AiConfigResult> {
  const url = `${getServerApiBase()}/apitokens/licenses/${encodeURIComponent(
    licenseId
  )}/ai-config`;
  const response = await fetch(url, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiToken}`,
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
    credentials: 'omit',
    mode: 'cors',
    signal,
  });
  const payload = (await response.json().catch(() => ({}))) as any;
  if (!response.ok) {
    return {
      success: false,
      message: payload?.message || response.statusText,
      error: payload?.error,
      needsModel: payload?.needsModel || payload?.error?.code === 'needs_model',
      triedModels: payload?.triedModels,
      suggestions: payload?.suggestions,
    };
  }
  return payload as AiConfigResult;
}
