import type { AIModel, AIModelsResponse } from '@/api/ai-models';
import { getAIModels } from '@/api/ai-models';
import { fetchServerModelList, type ServerModelItem } from '@/api/ai-server';

const ONE_HOUR_MS = 60 * 60 * 1000;
const FIVE_MINUTES_MS = 5 * 60 * 1000;
const SERVER_MODELS_STORAGE_KEY = 'zeroy_server_models_cache_v1';

type ServerStatus = 'success' | 'not_configured' | 'error' | 'skipped';

type ModelSource = 'server' | 'local' | 'none';

export interface UnifiedModel {
  id: string;
  name: string;
  description?: string;
  pricing?: Record<string, number | undefined>;
  [key: string]: unknown;
}

export interface ModelListResult {
  source: ModelSource;
  serverStatus: ServerStatus;
  serverConfigured: boolean;
  models: UnifiedModel[];
  provider?: string;
  baseUrl?: string;
  fetchedAt?: string;
  expiresAt?: string;
  raw?: unknown;
  listingSupported?: boolean;
  suggestions?: string[];
  serverErrorCode?: string;
  serverErrorMessage?: string;
  localUsed: boolean;
  localAvailable: boolean;
  localErrorMessage?: string;
}

interface ServerCacheSuccess {
  kind: 'success';
  expiresAt: number;
  result: ModelListResult;
}

interface ServerCacheFailure {
  kind: 'not_configured' | 'error';
  expiresAt: number;
  error?: {
    code?: string;
    message?: string;
  };
}

type ServerCacheEntry = ServerCacheSuccess | ServerCacheFailure;

interface LocalCacheEntry {
  expiresAt: number;
  baseUrl: string;
  apiKey: string;
  models: UnifiedModel[];
}

let serverCache: ServerCacheEntry | null = null;
let localCache: LocalCacheEntry | null = null;

const mapServerModels = (
  models: ServerModelItem[] | undefined
): UnifiedModel[] => {
  if (!models?.length) {
    return [];
  }
  return models.map((model) => {
    const { id, name, description, pricing, ...rest } = model;
    return {
      id,
      name: name || id,
      description,
      pricing,
      ...rest,
    };
  });
};

const mapLocalModels = (models: AIModel[] | undefined): UnifiedModel[] => {
  if (!models?.length) {
    return [];
  }
  return models.map((model) => {
    const { id, name, description, ...rest } = model;
    return {
      id,
      name: name || id,
      description,
      ...rest,
    };
  });
};

const createServerSuccessResult = (
  data: Awaited<ReturnType<typeof fetchServerModelList>> & {
    kind: 'success';
  }
): ModelListResult => {
  const models = mapServerModels(data.data.models);
  const expiresAt = Date.parse(data.data.expiresAt);
  const cacheExpiry = Number.isFinite(expiresAt)
    ? expiresAt
    : Date.now() + ONE_HOUR_MS;

  const result: ModelListResult = {
    source: 'server',
    serverStatus: 'success',
    serverConfigured: true,
    models,
    provider: data.data.provider,
    baseUrl: data.data.baseUrl,
    fetchedAt: data.data.fetchedAt,
    expiresAt: data.data.expiresAt,
    raw: data.data.raw,
    listingSupported: (data.data as any).listingSupported,
    suggestions: (data.data as any).suggestions,
    localUsed: false,
    localAvailable: false,
  };

  serverCache = {
    kind: 'success',
    result,
    expiresAt: cacheExpiry,
  };

  // Persist to localStorage for cross-reload caching
  try {
    localStorage.setItem(
      SERVER_MODELS_STORAGE_KEY,
      JSON.stringify(serverCache)
    );
  } catch {
    // ignore storage quota errors
  }

  return result;
};

const cacheServerFailure = (
  kind: Exclude<ServerCacheFailure['kind'], never>,
  error?: { code?: string; message?: string }
) => {
  serverCache = {
    kind,
    error,
    expiresAt: Date.now() + (kind === 'error' ? FIVE_MINUTES_MS : ONE_HOUR_MS),
  };
};

const readServerCache = (): ServerCacheEntry | null => {
  if (!serverCache) {
    // Attempt warm-up from localStorage
    try {
      const raw = localStorage.getItem(SERVER_MODELS_STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw) as ServerCacheEntry;
        if (
          parsed &&
          'kind' in parsed &&
          (parsed as any).expiresAt &&
          (parsed as any).expiresAt > Date.now()
        ) {
          serverCache = parsed;
        } else {
          localStorage.removeItem(SERVER_MODELS_STORAGE_KEY);
        }
      }
    } catch {
      // ignore
    }
    if (!serverCache) {
      return null;
    }
  }
  if (serverCache.expiresAt <= Date.now()) {
    serverCache = null;
    return null;
  }
  return serverCache;
};

const readLocalCache = (
  baseUrl?: string,
  apiKey?: string
): LocalCacheEntry | null => {
  if (!(baseUrl && apiKey)) {
    return null;
  }
  if (!localCache) {
    return null;
  }
  if (localCache.expiresAt <= Date.now()) {
    localCache = null;
    return null;
  }
  if (localCache.baseUrl !== baseUrl || localCache.apiKey !== apiKey) {
    return null;
  }
  return localCache;
};

const cacheLocalModels = (
  baseUrl: string,
  apiKey: string,
  models: UnifiedModel[]
) => {
  localCache = {
    baseUrl,
    apiKey,
    models,
    expiresAt: Date.now() + ONE_HOUR_MS,
  };
};

const resolveLocalModels = async (
  baseUrl: string,
  apiKey: string,
  serverStatus: ServerStatus,
  serverError?: { code?: string; message?: string },
  forceRefresh?: boolean
): Promise<ModelListResult> => {
  const cached = forceRefresh ? null : readLocalCache(baseUrl, apiKey);
  if (cached) {
    return {
      source: 'local',
      serverStatus,
      serverConfigured: false,
      models: cached.models,
      baseUrl,
      serverErrorCode: serverError?.code,
      serverErrorMessage: serverError?.message,
      localUsed: true,
      localAvailable: true,
    };
  }

  const response: AIModelsResponse = await getAIModels(baseUrl, apiKey);
  if (!(response.success && response.models)) {
    return {
      source: 'none',
      serverStatus,
      serverConfigured: false,
      models: [],
      baseUrl,
      serverErrorCode: serverError?.code,
      serverErrorMessage: serverError?.message,
      localUsed: true,
      localAvailable: true,
      localErrorMessage: response.error || '获取模型列表失败',
    };
  }

  const models = mapLocalModels(response.models);
  cacheLocalModels(baseUrl, apiKey, models);

  return {
    source: 'local',
    serverStatus,
    serverConfigured: false,
    models,
    baseUrl,
    serverErrorCode: serverError?.code,
    serverErrorMessage: serverError?.message,
    localUsed: true,
    localAvailable: true,
  };
};

interface ServerFetchOutcome {
  type: 'cache-hit' | 'success' | 'failure';
  result?: ModelListResult;
  status?: ServerStatus;
  error?: { code?: string; message?: string };
}

const hasModels = (models: UnifiedModel[] | undefined): boolean =>
  Array.isArray(models) && models.length > 0;

const mergeServerAndLocalResults = (
  serverResult: ModelListResult,
  localResult: ModelListResult
): ModelListResult => ({
  ...localResult,
  source: hasModels(localResult.models)
    ? localResult.source
    : serverResult.source,
  serverConfigured: serverResult.serverConfigured,
  serverStatus: 'success',
  provider: serverResult.provider,
  baseUrl: localResult.baseUrl ?? serverResult.baseUrl,
  fetchedAt: serverResult.fetchedAt,
  expiresAt: serverResult.expiresAt,
  raw: serverResult.raw,
  listingSupported: serverResult.listingSupported,
  suggestions: serverResult.suggestions,
  localAvailable: true,
  serverErrorCode: localResult.serverErrorCode,
  serverErrorMessage: localResult.serverErrorMessage,
});

interface ServerOutcomeHandling {
  result?: ModelListResult;
  status: ServerStatus;
  error?: { code?: string; message?: string };
}

const handleServerOutcome = async (
  outcome: ServerFetchOutcome,
  baseUrl: string | undefined,
  apiKey: string | undefined,
  forceRefresh: boolean | undefined
): Promise<ServerOutcomeHandling> => {
  if (
    (outcome.type === 'cache-hit' || outcome.type === 'success') &&
    outcome.result
  ) {
    const hasLocalConfig = Boolean(baseUrl && apiKey);
    const serverResult: ModelListResult = {
      ...outcome.result,
      localAvailable: hasLocalConfig,
    };

    if (!hasLocalConfig || hasModels(outcome.result.models)) {
      return { result: serverResult, status: 'success' };
    }

    if (!(baseUrl && apiKey)) {
      return { result: serverResult, status: 'success' };
    }

    const localResult = await resolveLocalModels(
      baseUrl,
      apiKey,
      'success',
      undefined,
      forceRefresh
    );

    return {
      result: mergeServerAndLocalResults(serverResult, localResult),
      status: 'success',
    };
  }

  return {
    status: outcome.status ?? 'skipped',
    error: outcome.error,
  };
};

const fetchServerModels = async (
  apiToken: string,
  forceRefresh: boolean | undefined,
  signal?: AbortSignal
): Promise<ServerFetchOutcome> => {
  const cached = forceRefresh ? null : readServerCache();

  if (cached) {
    if ('result' in cached) {
      return { type: 'cache-hit', result: cached.result };
    }
    return {
      type: 'failure',
      status: cached.kind,
      error: cached.error,
    };
  }

  try {
    const serverResult = await fetchServerModelList(apiToken, signal);
    if (serverResult.kind === 'success') {
      const result = createServerSuccessResult(serverResult);
      return { type: 'success', result };
    }

    const serverStatus: ServerStatus =
      serverResult.kind === 'not_configured' ? 'not_configured' : 'error';
    const serverError = {
      code: serverResult.code,
      message: serverResult.message,
    };
    cacheServerFailure(
      serverStatus === 'error' ? 'error' : 'not_configured',
      serverError
    );
    return {
      type: 'failure',
      status: serverStatus,
      error: serverError,
    };
  } catch (error: any) {
    const serverError = {
      message: error?.message || '请求服务端模型列表失败',
    };
    cacheServerFailure('error', serverError);
    return {
      type: 'failure',
      status: 'error',
      error: serverError,
    };
  }
};

export interface FetchModelListOptions {
  apiToken?: string;
  baseUrl?: string;
  apiKey?: string;
  forceRefresh?: boolean;
  signal?: AbortSignal;
}

export async function fetchModelListWithFallback(
  options: FetchModelListOptions
): Promise<ModelListResult> {
  const { apiToken, baseUrl, apiKey, forceRefresh, signal } = options;

  let serverStatus: ServerStatus = 'skipped';
  let serverError: { code?: string; message?: string } | undefined;

  if (apiToken) {
    const serverOutcome = await fetchServerModels(
      apiToken,
      forceRefresh,
      signal
    );

    const handled = await handleServerOutcome(
      serverOutcome,
      baseUrl,
      apiKey,
      forceRefresh
    );

    if (handled.result) {
      return handled.result;
    }

    serverStatus = handled.status;
    serverError = handled.error;
  }

  if (baseUrl && apiKey) {
    return resolveLocalModels(
      baseUrl,
      apiKey,
      serverStatus,
      serverError,
      forceRefresh
    );
  }

  return {
    source: 'none',
    serverStatus,
    serverConfigured: false,
    models: [],
    serverErrorCode: serverError?.code,
    serverErrorMessage: serverError?.message,
    localUsed: false,
    localAvailable: false,
  };
}

export function invalidateServerModelCache() {
  serverCache = null;
  try {
    localStorage.removeItem(SERVER_MODELS_STORAGE_KEY);
  } catch {
    // ignore storage access issues
  }
}

export function invalidateLocalModelCache() {
  localCache = null;
}
