interface AiSettingsLike {
  api_token?: string;
  base_url?: string;
  api_key?: string;
  [key: string]: unknown;
}

export interface AiCredentials {
  apiToken: string;
  baseUrl: string;
  apiKey: string;
  hasToken: boolean;
  hasLocalKey: boolean;
  hasCredentials: boolean;
}

const emptyCredentials: AiCredentials = {
  apiToken: '',
  baseUrl: '',
  apiKey: '',
  hasToken: false,
  hasLocalKey: false,
  hasCredentials: false,
};

export function extractAiCredentials(
  source?: AiSettingsLike | null
): AiCredentials {
  if (!source) {
    return emptyCredentials;
  }

  const rawToken = typeof source.api_token === 'string' ? source.api_token : '';
  const rawBaseUrl = typeof source.base_url === 'string' ? source.base_url : '';
  const rawApiKey = typeof source.api_key === 'string' ? source.api_key : '';

  const apiToken = rawToken.trim();
  const baseUrl = rawBaseUrl.trim();
  const apiKey = rawApiKey.trim();

  const hasToken = apiToken.length > 0;
  const hasLocalKey = baseUrl.length > 0 && apiKey.length > 0;

  return {
    apiToken,
    baseUrl,
    apiKey,
    hasToken,
    hasLocalKey,
    hasCredentials: hasToken || hasLocalKey,
  };
}

export type { AiSettingsLike };
